package com.acme.wallet;

import javax.enterprise.context.ApplicationScoped;
import javax.inject.Inject;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicReference;

@Path("/api/wallet")
@ApplicationScoped
@Produces(MediaType.APPLICATION_JSON)
@Consumes(MediaType.APPLICATION_JSON)
public class WalletResource {

    // In-memory ledger (simulating DB for serverless cold-start optimization)
    private final ConcurrentHashMap<String, AtomicReference<Double>> balances = new ConcurrentHashMap<>();

    @POST
    @Path("/init/{userId}")
    public Response initWallet(@PathParam("userId") String userId, @QueryParam("amount") double amount) {
        balances.put(userId, new AtomicReference<>(amount));
        return Response.ok("{\"status\":\"initialized\",\"balance\":" + amount + "}").build();
    }

    @POST
    @Path("/transfer")
    public Response transfer(@QueryParam("from") String from,
                            @QueryParam("to") String to,
                            @QueryParam("amount") double amount) {
        if (from == null || to == null || amount <= 0) {
            return Response.status(400).entity("{\"error\":\"invalid params\"}").build();
        }

        AtomicReference<Double> senderRef = balances.get(from);
        AtomicReference<Double> receiverRef = balances.get(to);

        if (senderRef == null || receiverRef == null) {
            return Response.status(404).entity("{\"error\":\"wallet not found\"}").build();
        }

        // VULNERABLE: check-then-act without atomic compare-and-swap
        // Read current balance
        double currentBalance = senderRef.get();

        // Simulate processing delay (DB lookup, audit log, etc.)
        try {
            Thread.sleep(50);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        // Check sufficiency AFTER delay - race window
        if (currentBalance < amount) {
            return Response.status(400).entity("{\"error\":\"insufficient funds\",\"balance\":" + currentBalance + "}").build();
        }

        // Non-atomic update: another thread may have already debited
        senderRef.set(currentBalance - amount);
        receiverRef.updateAndGet(v -> v + amount);

        return Response.ok("{\"status\":\"success\",\"newBalance\":" + senderRef.get() + "}").build();
    }

    @GET
    @Path("/balance/{userId}")
    public Response getBalance(@PathParam("userId") String userId) {
        AtomicReference<Double> ref = balances.get(userId);
        if (ref == null) {
            return Response.status(404).entity("{\"error\":\"not found\"}").build();
        }
        return Response.ok("{\"balance\":" + ref.get() + "}").build();
    }

    @GET
    @Path("/health")
    public Response health() {
        return Response.ok("{\"status\":\"UP\",\"wallets\":" + balances.size() + "}").build();
    }
}
